mapper.select:
SELECT id, user_id, title, content, source, status, reviewer_id, reviewed_at FROM t_health_report  AND id = #{id}
 AND user_id = #{userId}
 AND title LIKE CONCAT('%', #{title}, '%')
 AND source LIKE CONCAT('%', #{source}, '%')
 AND status LIKE CONCAT('%', #{status}, '%')
 AND reviewer_id = #{reviewerId}
 AND reviewed_at = #{reviewedAt} ORDER BY id DESC
